  press: { l: 'Competition (percentile)', g: 'C', ramp: 'slate', q: false, v: c => c.presspct, f: v => N(v, 0), note: 'Law offices per 1,000 married within the radius, raised where Competitor Watch logs live rival ads for the line in the county.' },
