      R('#lnCycSeg').innerHTML = post ? `<div class="seg" role="group" aria-label="Panel period" style="margin:0 0 8px"><button type="button" data-v="all" aria-pressed="${per === 'all'}">2019 to 2026</button><button type="button" data-v="post" aria-pressed="${per === 'post'}">2022 on</button></div>` : '';
