    const cols = [{ k: 'name', l: 'County', fmt: v => esc(v) }, { k: 'n', l: 'Matters 12mo', fmt: v => N(v), h: 'Matters, last 12 months', d: 0 }, { k: 'per10k', l: 'per 10k pop', fmt: v => N(v, 1), h: 'Matters per 10,000 residents', d: 1 }, { k: 'pool', l: 'Pool', fmt: v => isN(v) ? N(v) : 'not modeled', h: 'Pool', d: 0 }, { k: 'value', l: 'Value at 100%', fmt: v => $$$(v), h: 'Annual value at 100% share ($, value per matter from the shared store)', d: 0 }, { k: 'offices', l: 'Law offices', fmt: v => v ? N(v) : 'none (CBP)', h: 'Law offices (CBP 2023)', d: 0 }, { k: 'per_office', l: 'Matters/office', fmt: (v, r) => r.offices ? N(v, 1) : 'no office', h: 'Matters per law office', d: 1 }, { k: 'esi', l: 'Shock idx', fmt: v => N(v, 0), h: 'Economic Shock Index (percentile)', d: 0 }, { k: 'grade', l: 'Grade', fmt: v => `<span class="grade ${esc(v)}">${esc(v)}</span>`, h: 'Confidence grade' }];
    const rows = () => { const M = L(); const fee = SEV_MODEL.line(st.line).fee; return CTY.map(c => { const n = M.cnt(c); return { _id: c.fips, fips: c.fips, name: c.name, n, per10k: isN(n) ? n / c.pop2025 * 10000 : null, pool: M.pool(c), value: isN(n) && isN(fee) ? n * fee : null, offices: c.rates.lawoffices || 0, per_office: isN(n) && c.rates.lawoffices ? n / c.rates.lawoffices : null, esi: c.esi, grade: c.grade }; }); };
    const tbl = table(R('#lnTable'), { caption: 'Counties for the selected service line', cols, rows: rows(), sort: { k: 'n', dir: -1 }, onRow: id => { st.sel = id; store.set('sev.county', id); markSel(mapEl, id); play(); tbl.setSel(id); }, selected: st.sel });
    /* ---------- the ZIP view ---------- */
