        <div class="tblbox"><div class="tblwrap" style="max-height:420px"><table class="t"><caption class="vh">Every line in ${esc(z.zip)}, by contribution</caption><thead><tr><th scope="col" class="l">Line</th><th scope="col">Matters/yr</th><th scope="col">Contribution</th><th scope="col">Competition</th><th scope="col">Priority</th><th scope="col">Bid</th></tr></thead><tbody>${rowsL.map(({ id, c }) => `<tr class="${id === st.line ? 'sel' : ''}"><td class="l">${esc(LINE_META[id].short)}${LINE_META[id].kind === 'lens' ? ' <span class="ln-lensmark">lens</span>' : ''}${c.quiet ? ' <span class="pill">quiet</span>' : ''}</td><td>${N(c.matters, 1)}</td><td>${$$$(c.contrib)}</td><td>${N(c.presspct, 0)}</td><td>${N(c.pri, 0)}</td><td>${c.bid > 0 ? '+' : ''}${N(c.bid)}%</td></tr>`).join('')}</tbody></table></div></div>
