      const gridT = (gr, cap) => `<div class="tblbox"><div class="tblwrap"><table class="t ln-day"><caption class="vh">${esc(cap)}</caption><thead><tr><th scope="col"></th>${FLM.BLOCKS.map(b => `<th scope="col">${esc(b)}</th>`).join('')}</tr></thead><tbody>${FLM.DAYS.map((d, i) => `<tr><th scope="row">${d}</th>${gr[i].map(cell).join('')}</tr>`).join('')}</tbody></table></div></div>`;
