      const rs = FLM.allocate(st.metro, bud, st.month < 0 ? null : st.month, zs, alpha); const T = { b: sum(rs.map(r => r.budget)), leads: sum(rs.map(r => r.leads)), con: sum(rs.map(r => r.consults)), ret: sum(rs.map(r => r.retained)), rev: sum(rs.map(r => r.revenue)) };
      R('#lnPort').innerHTML = `<div class="tblbox"><div class="tblwrap"><table class="t"><caption class="vh">Portfolio allocation by line</caption><thead><tr><th scope="col" class="l">Line</th><th scope="col">Season</th><th scope="col">Contribution in scope</th><th scope="col">Media</th><th scope="col">Share</th><th scope="col">Cost per lead</th><th scope="col">Leads</th><th scope="col">Consultations</th><th scope="col">Retained</th><th scope="col">Value</th><th scope="col">Value per media $</th><th scope="col">Share of the month's paying matters</th></tr></thead><tbody>${rs.map(r => `<tr class="${r.id === st.line ? 'sel' : ''}"><td class="l">${esc(LINE_META[r.id].short)}</td><td>${N(r.season, 0)}</td><td>${$$$(r.contrib)}</td><td>${$$$(r.budget)}</td><td>${T.b > 0 ? P(r.budget / T.b, 0) : NA}</td><td>${$$$(r.u.cpl)}</td><td>${N(r.leads, 1)}</td><td>${N(r.consults, 1)}</td><td>${N(r.retained, 1)}</td><td>${$$$(r.revenue)}</td><td>${r.budget > 0 ? N(r.revenue / r.budget, 1) + '×' : NA}</td><td>${r.share != null ? P(r.share, 1) : NA}</td></tr>`).join('')}<tr class="ln-tot"><td class="l"><b>Total</b></td><td></td><td>${$$$(sum(rs.map(r => r.contrib)))}</td><td><b>${$$$(T.b)}</b></td><td>${T.b > 0 ? '100%' : NA}</td><td>${T.leads > 0 ? $$$(T.b / T.leads) : NA}</td><td><b>${N(T.leads, 1)}</b></td><td>${N(T.con, 1)}</td><td><b>${N(T.ret, 1)}</b></td><td><b>${$$$(T.rev)}</b></td><td>${T.b > 0 ? N(T.rev / T.b, 1) + '×' : NA}</td><td></td></tr></tbody></table></div></div>`;
      const monthly = MO.map((_, m) => FLM.allocate(st.metro, bud, m, zs, alpha)); const ann = {}; monthly.forEach(a => a.forEach(r => ann[r.id] = (ann[r.id] || 0) + r.budget)); const order = Object.keys(ann).sort((a, b) => ann[b] - ann[a]); const top = order.slice(0, 6), rest = order.slice(6);
      const cols0 = ['var(--s1)', 'var(--s3)', 'var(--s4)', 'var(--s5)', 'var(--s8)', 'var(--s6)']; const series = top.map((id, i) => ({ name: LINE_META[id].short, color: cols0[i], values: monthly.map(a => (a.find(r => r.id === id) || {}).budget || 0) })); if (rest.length) series.push({ name: 'Other lines', color: 'var(--ink-3)', values: monthly.map(a => sum(a.filter(r => rest.includes(r.id)).map(r => r.budget))) });
